import calendar
from datetime import date, timedelta

_WEEKDAYS = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])

    if freq == "DAILY":
        return [
            (start_date + timedelta(days=i * k)).isoformat()
            for i in range(count)
        ]

    res: list[str] = []

    if freq == "WEEKLY":
        weekdays = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week0 = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(res) < count:
            base = week0 + timedelta(weeks=w)
            for wd in weekdays:
                d = base + timedelta(days=wd)
                if d >= start_date:
                    res.append(d.isoformat())
                    if len(res) == count:
                        return res
            w += k
        return res

    if freq == "MONTHLY":
        start_months = start_date.year * 12 + (start_date.month - 1)
        m = 0
        if len(parts) == 3:
            day_spec = int(parts[2])
            while len(res) < count:
                year, month0 = divmod(start_months + m, 12)
                month = month0 + 1
                _, num_days = calendar.monthrange(year, month)
                day = num_days if day_spec == -1 else day_spec
                if day <= num_days:
                    d = date(year, month, day)
                    if d >= start_date:
                        res.append(d.isoformat())
                m += k
        else:
            n = int(parts[2])
            target_wd = _WEEKDAYS[parts[3]]
            while len(res) < count:
                year, month0 = divmod(start_months + m, 12)
                month = month0 + 1
                first_wd, num_days = calendar.monthrange(year, month)
                if n == -1:
                    last_wd = (first_wd + num_days - 1) % 7
                    day = num_days - (last_wd - target_wd) % 7
                else:
                    first_occ = 1 + (target_wd - first_wd) % 7
                    day = first_occ + (n - 1) * 7
                if day <= num_days:
                    d = date(year, month, day)
                    if d >= start_date:
                        res.append(d.isoformat())
                m += k
        return res

    if freq == "YEARLY":
        mm_str, dd_str = parts[2].split("-")
        mm, dd = int(mm_str), int(dd_str)
        year = start_date.year
        while len(res) < count:
            try:
                d = date(year, mm, dd)
            except ValueError:
                pass
            else:
                if d >= start_date:
                    res.append(d.isoformat())
            year += k
        return res

    raise ValueError(f"Unknown rule: {rule}")
